"""Comprehensive Library Subject Thesaurus and Synonym Expansion Graph.

Enables query expansion and semantic search recall across multi-disciplinary concepts.
"""

from typing import Dict, List, Set, Optional
from dataclasses import dataclass, field


@dataclass
class ThesaurusConcept:
    preferred_label: str
    alternate_labels: List[str] = field(default_factory=list)
    broader_concepts: List[str] = field(default_factory=list)
    narrower_concepts: List[str] = field(default_factory=list)
    related_concepts: List[str] = field(default_factory=list)


THESAURUS_GRAPH: Dict[str, ThesaurusConcept] = {}

def _concept(pref: str, alt: List[str], broader: List[str], narrower: List[str], related: List[str]):
    THESAURUS_GRAPH[pref.lower()] = ThesaurusConcept(pref, alt, broader, narrower, related)

