def expand_thesaurus_query(term: str) -> Set[str]:
    clean = term.strip().lower()
    expanded = {clean}
    if clean in THESAURUS_GRAPH:
        c = THESAURUS_GRAPH[clean]
        expanded.update(a.lower() for a in c.alternate_labels)
        expanded.update(n.lower() for n in c.narrower_concepts)
        expanded.update(r.lower() for r in c.related_concepts)
    return expanded
